const $=id=>document.getElementById(id);
const phases=[
{name:'Segar',at:0,range:'Awal perjalanan',label:'Kulit hijau & kencang',sub:'Awal perjalanan',desc:'Mangga masih hijau dengan permukaan yang kencang. Proses pematangan mulai berlangsung di dalam buah.',texture:'Keras & padat',aroma:'Segar, ringan',colors:['#b3d45f','#73a638','#305d28'],mini:'#86b94c'},
{name:'Matang',at:3,range:'Pematangan',label:'Warna kuning keemasan',sub:'Tekstur mulai melunak',desc:'Warna kulit beralih ke kuning keemasan. Daging buah melunak dan aroma manis menjadi lebih terasa.',texture:'Lunak & kenyal',aroma:'Manis, harum',colors:['#ffe48b','#efb52d','#a47b1f'],mini:'#efc34b'},
{name:'Terlalu matang',at:6,range:'Pematangan lanjut',label:'Bercak mulai muncul',sub:'Permukaan semakin lunak',desc:'Kulit mulai berbintik kecokelatan dan tekstur semakin lembek. Perubahan warna tampak semakin jelas.',texture:'Lembek',aroma:'Manis menyengat',colors:['#e3c16a','#c28b2e','#716024'],mini:'#c99b3e'},
{name:'Mulai membusuk',at:9,range:'Pembusukan awal',label:'Bercak gelap meluas',sub:'Jamur mulai terlihat',desc:'Bercak gelap meluas, permukaan mengerut, dan pertumbuhan jamur mulai tampak pada ilustrasi.',texture:'Sangat lembek',aroma:'Asam, fermentasi',colors:['#a2914b','#786234','#3d4327'],mini:'#847340'},
{name:'Membusuk',at:12,range:'Pembusukan lanjut',label:'Jamur & kulit mengerut',sub:'Struktur buah melemah',desc:'Buah menjadi gelap dan mengerut. Area jamur meluas seiring penguraian jaringan buah pada fase akhir simulasi.',texture:'Lunak & mengerut',aroma:'Busuk, kuat',colors:['#716449','#494832','#272c23'],mini:'#51533b'}
];
const environments={room:{rate:1,label:'SUHU RUANG · 28°C'},cold:{rate:.55,label:'TEMPAT SEJUK · 15°C'},warm:{rate:1.4,label:'TEMPAT HANGAT · 35°C'}};
let time=0,environment='room',playing=false,speed=1,lastFrame=null,currentPhase=-1;
const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
const mix=(a,b,t)=>{const rgb=h=>h.match(/\w\w/g).map(v=>parseInt(v,16));const aa=rgb(a.slice(1)),bb=rgb(b.slice(1));return '#'+aa.map((v,i)=>Math.round(v+(bb[i]-v)*t).toString(16).padStart(2,'0')).join('');};
let seed=73;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
function svg(tag,attrs,parent){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
for(let i=0;i<260;i++)svg('circle',{cx:175+random()*285,cy:95+random()*280,r:.4+random()*.8,fill:i%3?'#d9de8b':'#344e24',opacity:.15+random()*.28},$('speckles'));
const bruises=Array.from({length:27},()=>{const start=4.5+random()*7;return {start,e:svg('ellipse',{cx:190+random()*255,cy:115+random()*240,rx:8+random()*28,ry:6+random()*23,fill:'url(#bruise)',opacity:0},$('bruises'))};});
const molds=Array.from({length:18},()=>{const start=8.4+random()*4.8;const g=svg('g',{opacity:0},$('molds'));const x=205+random()*225,y=125+random()*200;for(let j=0;j<9;j++)svg('circle',{cx:x+(random()-.5)*25,cy:y+(random()-.5)*23,r:4+random()*13,fill:'url(#mold)'},g);return {start,e:g};});
for(let i=0;i<18;i++){const x=195+random()*240,y=160+random()*170;svg('path',{d:`M${x} ${y} q-12 15 -3 32 q7 12 0 23`,stroke:'#302d22','stroke-width':.7+random(),fill:'none',opacity:.35},$('wrinkles'));}
phases.forEach((p,i)=>{const b=document.createElement('button');b.className='phase-card';b.innerHTML=`<span class="mini-mango" style="background:${p.mini}"></span><span><strong>${p.name}</strong><small>Amati fase ini</small></span>`;b.addEventListener('click',()=>{setPlaying(false);time=Math.min(14,p.at/environments[environment].rate);render();});$('phaseCards').append(b);});
function setPlaying(value){playing=value;lastFrame=null;$('playIcon').textContent=value?'Ⅱ':'▶';$('playText').textContent=value?'Jeda simulasi':time>=14?'Putar ulang':'Mulai simulasi';$('play').setAttribute('aria-label',value?'Jeda simulasi':'Mulai simulasi');}
function render(){const age=Math.min(14,time*environments[environment].rate);let index=0;phases.forEach((p,i)=>{if(age>=p.at)index=i;});const p=phases[index],next=phases[Math.min(index+1,4)],blend=clamp((age-p.at)/((next.at-p.at)||1));
for(let i=0;i<3;i++)$('color'+(i+1)).setAttribute('stop-color',mix(p.colors[i],next.colors[i],blend));
globalThis.mango3D?.update(age,p.colors.map((color,i)=>mix(color,next.colors[i],blend)));
bruises.forEach(({start,e})=>e.setAttribute('opacity',clamp((age-start)/3)*.9));molds.forEach(({start,e})=>e.setAttribute('opacity',clamp((age-start)/2.5)*.95));$('wrinkles').setAttribute('opacity',clamp((age-7)/7));$('fruit').style.transform=`translateY(${clamp((age-8)/6)*13}px) scale(${1-clamp((age-8)/6)*.025},${1-clamp((age-8)/6)*.1})`;$('leaf').style.opacity=1-clamp(age/14)*.65;
const parts=time.toFixed(1).split('.');$('day').innerHTML=parts[0].padStart(2,'0')+'<span>.'+parts[1]+'</span>';$('time').value=time;$('timeValue').value='Hari '+time.toFixed(1).replace('.',',');$('environmentLabel').textContent=environments[environment].label;
const freshness=Math.round(clamp(1-age/14)*100);$('freshValue').textContent=freshness+'%';$('freshBar').style.width=freshness+'%';$('phaseBadge').textContent='FASE 0'+(index+1)+' / 05';
if(currentPhase!==index){currentPhase=index;$('phaseName').textContent=p.name;$('phasePeriod').textContent=p.range;$('phaseDesc').textContent=p.desc;$('textureText').textContent=p.texture;$('aromaText').textContent=p.aroma;$('visualLabel').textContent=p.label;$('visualSub').textContent=p.sub;$('mangoTitle').textContent='Ilustrasi mangga pada fase '+p.name.toLowerCase();}
document.querySelectorAll('.phase-card').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-pressed',i===index?'true':'false');const reachable=phases[i].at/environments[environment].rate<=14;b.disabled=!reachable;b.title=reachable?'Amati fase '+phases[i].name:'Fase ini belum tercapai dalam 14 hari pada kondisi sejuk';b.style.opacity=reachable?'1':'.45';});}
$('play').addEventListener('click',()=>{if(!playing&&time>=14)time=0;setPlaying(!playing);render();});$('reset').addEventListener('click',()=>{setPlaying(false);time=0;render();});$('time').addEventListener('input',e=>{time=Number(e.target.value);render();});$('speed').addEventListener('change',e=>speed=Number(e.target.value));document.querySelectorAll('[data-env]').forEach(b=>b.addEventListener('click',()=>{environment=b.dataset.env;document.querySelectorAll('[data-env]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b?'true':'false');});render();}));
function frame(timestamp){if(playing){if(lastFrame!==null)time=Math.min(14,time+Math.min((timestamp-lastFrame)/1000,.1)*.4*speed);lastFrame=timestamp;if(time>=14)setPlaying(false);render();}requestAnimationFrame(frame);}document.addEventListener('visibilitychange',()=>lastFrame=null);
$('about').addEventListener('click',()=>$('aboutDialog').showModal());$('closeAbout').addEventListener('click',()=>$('aboutDialog').close());$('aboutDialog').addEventListener('click',e=>{if(e.target===$('aboutDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();requestAnimationFrame(frame);
